CREATE TABLE "TB_DATA_CORR_HIS" (
  "CORR_ID" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "PROVIDER_CD" VARCHAR(30) NOT NULL,
  "DATASET_CD" VARCHAR(100) NOT NULL,
  "SOURCE_KEY" VARCHAR(500) NOT NULL,
  "BASE_DT" DATE,
  "CHANGED_COLS" JSONB NOT NULL,
  "BEFORE_PAYLOAD" JSONB NOT NULL,
  "AFTER_PAYLOAD" JSONB NOT NULL,
  "PAYLOAD_VER" INTEGER NOT NULL,
  "RECOLLECT_JOB_ID" UUID,
  "CORR_REASON" VARCHAR(1000) NOT NULL,
  "DETECTED_DTTM" TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE "TB_RECALC_QUEUE" (
  "RECALC_ID" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "CORR_ID" BIGINT NOT NULL REFERENCES "TB_DATA_CORR_HIS"("CORR_ID") ON DELETE CASCADE,
  "TARGET_TP" VARCHAR(40) NOT NULL,
  "BASE_DT" DATE,
  "STATUS" VARCHAR(30) NOT NULL DEFAULT 'PENDING',
  "ATTEMPT_CNT" INTEGER NOT NULL DEFAULT 0,
  "ERROR_MSG" VARCHAR(4000),
  "CRT_DTTM" TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "START_DTTM" TIMESTAMP WITH TIME ZONE,
  "COMPLETE_DTTM" TIMESTAMP WITH TIME ZONE,
  CONSTRAINT "UK_TB_RECALC_QUEUE_01" UNIQUE("CORR_ID","TARGET_TP"),
  CONSTRAINT "CK_TB_RECALC_QUEUE_01" CHECK("STATUS" IN ('PENDING','RUNNING','COMPLETED','FAILED','IGNORED'))
);

CREATE INDEX "IDX_TB_DATA_CORR_HIS_01" ON "TB_DATA_CORR_HIS"("PROVIDER_CD","BASE_DT" DESC);
CREATE INDEX "IDX_TB_RECALC_QUEUE_01" ON "TB_RECALC_QUEUE"("STATUS","BASE_DT");

CREATE OR REPLACE FUNCTION "FN_AUDIT_PROVIDER_CORRECTION"() RETURNS trigger AS $$
DECLARE
  old_payload jsonb := to_jsonb(OLD);
  new_payload jsonb := to_jsonb(NEW);
  changes jsonb;
  correction_id bigint;
  source_date date;
  source_key text;
  next_version integer;
BEGIN
  SELECT jsonb_object_agg(key, jsonb_build_object('before',old_payload->key,'after',new_payload->key))
    INTO changes
  FROM (SELECT key FROM jsonb_object_keys(old_payload) key
        UNION SELECT key FROM jsonb_object_keys(new_payload) key) keys
  WHERE old_payload->key IS DISTINCT FROM new_payload->key
    AND key NOT IN ('COLLECT_DTTM','UPD_DTTM','MOD_DT','REG_DT','LAST_COLLECT_DTTM');
  IF changes IS NULL OR changes = '{}'::jsonb THEN RETURN NEW; END IF;

  source_date := COALESCE(
    NULLIF(new_payload->>'BASE_DT','')::date,
    NULLIF(new_payload->>'TRADE_DT','')::date,
    NULLIF(new_payload->>'OBS_DT','')::date);
  source_key := TG_TABLE_NAME || ':' || COALESCE(source_date::text,'NO_DATE') || ':' || concat_ws('|',
    new_payload->>'STK_ID',new_payload->>'STK_CD',new_payload->>'IDX_CD',new_payload->>'BOND_CD',
    new_payload->>'SERIES_ID',new_payload->>'ISU_CD',new_payload->>'DATASET_CD',
    new_payload->>'BASE_CURR_CD',new_payload->>'QUOTE_CURR_CD');
  SELECT COALESCE(max("PAYLOAD_VER"),0)+1 INTO next_version
    FROM "TB_DATA_CORR_HIS" WHERE "PROVIDER_CD"=TG_ARGV[0] AND "DATASET_CD"=TG_ARGV[1]
      AND "SOURCE_KEY"=source_key;

  INSERT INTO "TB_DATA_CORR_HIS"("PROVIDER_CD","DATASET_CD","SOURCE_KEY","BASE_DT",
    "CHANGED_COLS","BEFORE_PAYLOAD","AFTER_PAYLOAD","PAYLOAD_VER","CORR_REASON")
  VALUES(TG_ARGV[0],TG_ARGV[1],source_key,source_date,changes,old_payload,new_payload,next_version,
    'PROVIDER_RECOLLECTION_VALUE_CHANGED') RETURNING "CORR_ID" INTO correction_id;

  INSERT INTO "TB_RECALC_QUEUE"("CORR_ID","TARGET_TP","BASE_DT") VALUES
    (correction_id,'MARKET_SNAPSHOT',source_date),
    (correction_id,'MARKET_SENTIMENT',source_date),
    (correction_id,'INVESTMENT_DECISION',source_date),
    (correction_id,'BRIEFING',source_date);
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER "TRG_PRC_DAY_CORR" AFTER UPDATE ON "TB_PRC_DAY" FOR EACH ROW EXECUTE FUNCTION "FN_AUDIT_PROVIDER_CORRECTION"('MARKET_DATA','PRICE_DAY');
CREATE TRIGGER "TRG_IDX_DAY_CORR" AFTER UPDATE ON "TB_IDX_DAY" FOR EACH ROW EXECUTE FUNCTION "FN_AUDIT_PROVIDER_CORRECTION"('MARKET_DATA','INDEX_DAY');
CREATE TRIGGER "TRG_EXCH_DAY_CORR" AFTER UPDATE ON "TB_EXCH_DAY" FOR EACH ROW EXECUTE FUNCTION "FN_AUDIT_PROVIDER_CORRECTION"('MARKET_DATA','EXCHANGE_DAY');
CREATE TRIGGER "TRG_FRED_OBS_CORR" AFTER UPDATE ON "TB_FRED_OBS" FOR EACH ROW EXECUTE FUNCTION "FN_AUDIT_PROVIDER_CORRECTION"('FRED','OBSERVATION');
CREATE TRIGGER "TRG_FRED_BOND_CORR" AFTER UPDATE ON "TB_FRED_BOND_DAY" FOR EACH ROW EXECUTE FUNCTION "FN_AUDIT_PROVIDER_CORRECTION"('FRED','BOND_DAY');
CREATE TRIGGER "TRG_KOFIA_CRDT_CORR" AFTER UPDATE ON "TB_KOFIA_CRDT_BAL_DAY" FOR EACH ROW EXECUTE FUNCTION "FN_AUDIT_PROVIDER_CORRECTION"('KOFIA','CREDIT_BALANCE_TREND');
CREATE TRIGGER "TRG_DERIV_DAY_CORR" AFTER UPDATE ON "TB_DERIV_DAY" FOR EACH ROW EXECUTE FUNCTION "FN_AUDIT_PROVIDER_CORRECTION"('KRX','DERIVATIVE_DAY');
CREATE TRIGGER "TRG_BOND_TRD_CORR" AFTER UPDATE ON "TB_BOND_TRD_DAY" FOR EACH ROW EXECUTE FUNCTION "FN_AUDIT_PROVIDER_CORRECTION"('KRX','BOND_TRADING_DAY');

COMMENT ON TABLE "TB_DATA_CORR_HIS" IS '공급자 재수집 값 정정 전후 및 변경 컬럼 이력';
COMMENT ON TABLE "TB_RECALC_QUEUE" IS '정정 데이터로 인해 재계산해야 하는 downstream 대상';
